// Package db opens the PostgreSQL connection pool. The typed queries that run
// on it are generated by sqlc into internal/dbgen.
package db

import (
	"context"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
)

// connectTimeout bounds the startup ping, so a wrong host fails in seconds
// instead of hanging the process.
const connectTimeout = 5 * time.Second

// Connect opens a pool for databaseURL and checks that the database answers.
// Callers own the pool and must Close it.
//
// pgxpool.New does not dial anything until it is used, so the ping is what turns
// a bad URL or an unreachable database into an error at startup.
func Connect(ctx context.Context, databaseURL string) (*pgxpool.Pool, error) {
	if databaseURL == "" {
		return nil, fmt.Errorf("DATABASE_URL is required")
	}
	pool, err := pgxpool.New(ctx, databaseURL)
	if err != nil {
		return nil, fmt.Errorf("open database pool: %w", err)
	}

	pingCtx, cancel := context.WithTimeout(ctx, connectTimeout)
	defer cancel()
	if err := pool.Ping(pingCtx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("reach database: %w", err)
	}
	return pool, nil
}
